class Solution:
    def longestWPI(self, hours: List[int]) -> int:
        n = len(hours)
        ans = 0
        for i in range(n):
            tiring = 0
            for j in range(i, n):
                if hours[j] > 8:
                    tiring += 1
                else:
                    tiring -= 1
                if tiring > 0:
                    ans = max(ans, j - i + 1)
        return ans

