public:
    int longestWPI(vector<int>& hours) {
        unordered_map<int, int> first{{0, -1}};
        int score = 0, ans = 0;
        for (int i = 0; i < (int)hours.size(); i++) {
            score += hours[i] > 8 ? 1 : -1;
            if (score > 0) ans = i + 1;
            else {
                auto it = first.find(score - 1);
                if (it != first.end()) ans = max(ans, i - it->second);
            }
            if (!first.count(score)) first[score] = i;
        }
        return ans;
    }
};

