class Solution:
    def longestWPI(self, hours: List[int]) -> int:
        n = len(hours)
        p = [0]
        for h in hours:
            p.append(p[-1] + (1 if h > 8 else -1))
        stack = []
        for i in range(n + 1):
            if not stack or p[i] < p[stack[-1]]:
                stack.append(i)
        ans = 0
        for j in range(n, 0, -1):
            while stack and p[j] > p[stack[-1]]:
                ans = max(ans, j - stack.pop())
        return ans

