class Solution {
public:
    int longestWPI(vector<int>& hours) {
        int n = hours.size();
        vector<int> p(n + 1, 0);
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + (hours[i] > 8 ? 1 : -1);
        vector<int> st;
        for (int i = 0; i <= n; i++)
            if (st.empty() || p[i] < p[st.back()]) st.push_back(i);
        int ans = 0;
        for (int j = n; j >= 1 && !st.empty(); j--)
            while (!st.empty() && p[j] > p[st.back()])
                ans = max(ans, j - st.back()), st.pop_back();
        return ans;
    }
};

