class Solution {
    public int longestWPI(int[] hours) {
        int n = hours.length;
        int[] p = new int[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + (hours[i] > 8 ? 1 : -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i <= n; i++)
            if (st.isEmpty() || p[i] < p[st.peek()]) st.push(i);
        int ans = 0;
        for (int j = n; j >= 1 && !st.isEmpty(); j--)
            while (!st.isEmpty() && p[j] > p[st.peek()])
                ans = Math.max(ans, j - st.pop());
        return ans;
    }
}

